    @Test
    public void vignetting_factors() {
        var fields = build().optical_spec.fov.fields;
        assertClose("fld.0.vlx", -3.2783332092622963E-4d, fields[0].vlx, 1.0e-6);
        assertClose("fld.0.vly", -3.2783332092622963E-4d, fields[0].vly, 1.0e-6);
        assertClose("fld.0.vux", -3.2783332092622963E-4d, fields[0].vux, 1.0e-6);
        assertClose("fld.0.vuy", -3.2783332092622963E-4d, fields[0].vuy, 1.0e-6);
        assertClose("fld.1.vlx", 0.08705058074841399d, fields[1].vlx, 1.0e-6);
        assertClose("fld.1.vly", 0.43224201932614736d, fields[1].vly, 1.0e-6);
        assertClose("fld.1.vux", 0.08705058074841399d, fields[1].vux, 1.0e-6);
        assertClose("fld.1.vuy", 0.2920011487326528d, fields[1].vuy, 1.0e-6);
        assertClose("fld.2.vlx", 0.2161214845003241d, fields[2].vlx, 1.0e-6);
        assertClose("fld.2.vly", 0.6596694008968174d, fields[2].vly, 1.0e-6);
        assertClose("fld.2.vux", 0.2161214845003241d, fields[2].vux, 1.0e-6);
        assertClose("fld.2.vuy", 0.6037534281009107d, fields[2].vuy, 1.0e-6);
    }

    @Test
    public void chief_ray_aiming() {
        var fields = build().optical_spec.fov.fields;
        Assertions.assertNotNull(fields[0].aim_info, "aim.0.x - expected paraxial aiming");
        assertClose("aim.0.x", 0.0d, fields[0].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[0].aim_info, "aim.0.y - expected paraxial aiming");
        assertClose("aim.0.y", 0.0d, fields[0].aim_info[1], 1.0e-6);
        Assertions.assertNotNull(fields[1].aim_info, "aim.1.x - expected paraxial aiming");
        assertClose("aim.1.x", 0.0d, fields[1].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[1].aim_info, "aim.1.y - expected paraxial aiming");
        assertClose("aim.1.y", 0.2695154184433682d, fields[1].aim_info[1], 1.0e-6);
        Assertions.assertNotNull(fields[2].aim_info, "aim.2.x - expected paraxial aiming");
        assertClose("aim.2.x", 0.0d, fields[2].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[2].aim_info, "aim.2.y - expected paraxial aiming");
        assertClose("aim.2.y", 0.8656855834279538d, fields[2].aim_info[1], 1.0e-6);
    }

