        assertClose("ray.1.2.1.n.x", 0.2127824970869642d, s1.nrml.x, 1.0e-6);
        assertClose("ray.1.2.1.n.y", -0.15606755818646034d, s1.nrml.y, 1.0e-6);
        assertClose("ray.1.2.1.n.z", 0.9645550923690943d, s1.nrml.z, 1.0e-6);
        assertClose("ray.1.2.1.dst", 8.150790692202866d, s1.dst, 1.0e-6);
        var s2 = pkg.ray.get(2);
        assertClose("ray.1.2.2.p.x", 16.727544766399795d, s2.p.x, 1.0e-6);
        assertClose("ray.1.2.2.p.y", -10.935686941498194d, s2.p.y, 1.0e-6);
